with with_windows as (select *, avg(salary) over (partition by job_title, level order by salary, id rows between 6 preceding and 1 preceding) as salary_avg_6_prior, stddev_samp(salary) over (partition by month(hire_date)) as hire_date_month_stddev_samp_salary, row_number() over (order by hire_date desc, id) as seq_no, ntile(3) over (order by salary desc, id) as salary_bucket, percent_rank() over (partition by dept_id order by salary) as salary_percent_rank from employees where length(email) > 7) select case when salary_percent_rank >= 0.82 then 'PREMIUM' else 'STANDARD' end as salary_percent_rank_tier, count_if(job_title = 'Manager') as manager_events, percentile_approx(hire_date_month_stddev_samp_salary, 0.95) as hire_date_month_stddev_samp_salary_p95 from with_windows group by case when salary_percent_rank >= 0.82 then 'PREMIUM' else 'STANDARD' end order by manager_events;
